<?php
require_once __DIR__.'/production.php';$recipes=productionRecipes();$rows=[];$materials=[];
foreach($recipes as $id=>$r){$per=productionMaterials($r,1000);foreach($per as $m=>$g)$materials[$m]=true;$rows[]=['id'=>$id,'name'=>$r['name'],'per'=>$per];}
$missing=query('SELECT DISTINCT p.name FROM products p LEFT JOIN production_links l ON l.product_id=p.id LEFT JOIN production_recipes r ON r.id=l.recipe_id AND r.active=1 WHERE p.active=1 AND r.id IS NULL ORDER BY p.name')->fetchAll(PDO::FETCH_COLUMN);
foreach($missing as $name)$rows[]=['id'=>0,'name'=>$name,'per'=>[]];
?>
<div class="toolbar"><a class="button secondary" href="/?page=production">← 생산 계획</a><button type="button" class="button secondary" id="clear-materials">모두 지우기</button></div>
<section class="panel"><h2>몇 kg을 만들까요?</h2><p class="hint">입력 즉시 재료 구입량이 바뀝니다. 입력값은 저장하지 않습니다. 아래 값은 현재 주재료 배합 기준이며 양념 등 등록하지 않은 재료는 포함하지 않습니다.</p><div class="table-wrap"><table id="material-calculator"><thead><tr><th>제품 / 배합</th><th>생산 무게(kg)</th><?php foreach($materials as $m=>$yes): ?><th><?=e($m)?> (kg)</th><?php endforeach ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr data-material-factors="<?=e(json_encode($row['per'],JSON_UNESCAPED_UNICODE))?>"><th><?=e($row['name'])?><?php if(!$row['per']): ?><small>배합 기준 확인 필요</small><?php endif ?></th><td><input type="number" class="material-weight" min="0" max="100000" step="0.01" value="0" <?=$row['per']?'':'disabled'?> aria-label="<?=e($row['name'])?> 생산 kg"></td><?php foreach($materials as $m=>$yes): ?><td data-material="<?=e($m)?>">0</td><?php endforeach ?></tr><?php endforeach ?></tbody><tfoot><tr class="comparison-total"><th>합계</th><td id="material-weight-total">0 kg</td><?php foreach($materials as $m=>$yes): ?><td data-material-total="<?=e($m)?>">0</td><?php endforeach ?></tr></tfoot></table></div></section>
